private static Connected connect(int port) {
    HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
    URI uri = URI.create("ws://127.0.0.1:" + port + "/hcp/v1");
    RuntimeException latest = null;
    for (int attempt = 0; attempt < 20; attempt++) {
        var listener = new Listener();
        try {
            return new Connected(client.newWebSocketBuilder().connectTimeout(Duration.ofSeconds(2))
                    .buildAsync(uri, listener).join(), listener);
        } catch (RuntimeException failure) {
            latest = failure;
            try {
                Thread.sleep(500);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("Remote HCP connection was interrupted", interrupted);
            }
        }
    }
    throw new IllegalStateException("Remote HCP tunnel did not become ready", latest);
}

